{{
  (() => {
    const emoji = "🔨"; 
    const data = Get_Atelier_Global.data || [];

    // 1. On compte le total d'interventions (en excluant les faux bandeaux de séparation)
    const vraiesInterventions = data.filter(row => !row.isHeader);
    const totalCount = vraiesInterventions.length;

    // 2. On prépare les compteurs par catégorie
    let count2T = 0;
    let count4T = 0;
    let countRobot = 0;

    // 3. On boucle sur les données pour reproduire la formule de comptage d'AppSheet
    vraiesInterventions.forEach(row => {
        const categorie = (row.Categorie_Materiel || "").toUpperCase();
        const statut = (row.Statut || "").toUpperCase();

        // On exclut certains statuts du décompte (comme dans ton code AppSheet)
        if (statut !== "PRÊT" && statut !== "H.S." && statut !== "LIVRÉ.FACTURÉ" && statut !== "FACTURE") {
            if (categorie === "2T") count2T++;
            if (categorie === "4T") count4T++;
            if (categorie === "ROBOT") countRobot++;
        }
    });

    // 4. On génère le texte final
    // On récupère le prénom, et si la requête charge on affiche "PERSO" par défaut
const prenom = Get_Mecano_Connecte.data?.[0]?.Prenom ? Get_Mecano_Connecte.data[0].Prenom.toUpperCase() : "PERSO";

return `${emoji} ATELIER ${prenom} (${totalCount}) : 2T (${count2T}) - 4T (${count4T}) - Robot (${countRobot})`;
  })()
}}
